import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.SetPlayerInventoryOptions{LeftInventoryTab: packet.InventoryLeftTabSurvival,
# RightInventoryTab: packet.InventoryRightTabArmour, Filtering: true,
# InventoryLayout: packet.InventoryLayoutDefault, CraftingLayout: packet.InventoryLayoutInventoryOnly}
SURVIVAL = bytes.fromhex("0c06010402")

# generated by gophertunnel b8bd735:
# packet.SetPlayerInventoryOptions{LeftInventoryTab: 100, RightInventoryTab: packet.InventoryRightTabNone,
# Filtering: false, InventoryLayout: -1, CraftingLayout: packet.InventoryLayoutNone}
UNNAMED = bytes.fromhex("c80100000100")

GOLDENS = [
    pytest.param(
        v2225.SetPlayerInventoryOptionsPacket(
            inventory_options=v2225.InventoryOptions(
                left_inventory_tab=v2225.InventoryLeftTabIndex.SURVIVAL,
                right_inventory_tab=v2225.InventoryRightTabIndex.ARMOR,
                filtering=True,
                layout_inv=v2225.InventoryLayout.DEFAULT,
                layout_craft=v2225.InventoryLayout.INVENTORY_ONLY,
            )
        ),
        SURVIVAL,
        id="survival",
    ),
    pytest.param(
        v2225.SetPlayerInventoryOptionsPacket(
            inventory_options=v2225.InventoryOptions(
                left_inventory_tab=100,
                right_inventory_tab=v2225.InventoryRightTabIndex.NONE,
                filtering=False,
                layout_inv=-1,
                layout_craft=v2225.InventoryLayout.NONE,
            )
        ),
        UNNAMED,
        id="unnamed-values",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_player_inventory_options_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_player_inventory_options_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
